 const wood=mat('#95714d'),woodDark=mat('#6d5545'),stone=mat('#9fa698'),cream=mat('#f2e8ce'),roof=mat(mountain?'#635e57':'#a96350'),trunk=mat('#76614c'),dark=mat('#3c4f45'),gold=mat('#c6a565');
